window.FILM_WORK_PROMPTS={"work_id":"src-59830252dba54de0","records":[{"work_id":"src-59830252dba54de0","frame_id":"FG-816cf741d94f69a5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_07.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"昏暗冷调环境中，粗糙纹理的深色台面上散落着金属钥匙串、深色扁平物件与一个黑色遥控器，背景虚化模糊。","analysis":"画面采用低角度近摄，景深极浅，焦点集中在前景的钥匙与遥控器上。整体光线昏暗，呈现冷蓝色调，物体表面有微弱反光。背景完全虚化，无法辨认具体环境细节，营造出一种压抑、静谧的视觉氛围。","prompt":"昏暗冷调的静物特写，粗糙纹理的深色台面上散落着几把金属钥匙、一个深色扁平物件和一个黑色遥控器。画面采用低角度近摄，景深极浅，焦点集中在前景的钥匙与遥控器上，背景完全虚化。整体光线昏暗，呈现冷蓝色调，物体表面有微弱反光，营造出一种压抑、静谧的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:23:06-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_07.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.121,"observed_resolution":"normal","observation_limits":[],"id":"VP-48d908a0813d6356","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-3acf6ac0262d2f9c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_20.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"短发人物背对镜头站立，肩背裸露，下围白色织物。左侧镜中映出面部，手指触碰脸颊。背景为蓝绿色瓷砖墙面，光线昏暗。","analysis":"人物背部占据画面右侧及下方约三分之二区域，镜中反射位于左侧。人物上半身及肩背可见，头部及面部通过镜面呈现。视角平视，光线从左侧微弱射入，整体呈冷蓝色调，背部皮肤在暗光下呈现柔和的明暗过渡，环境瓷砖纹理清晰。","prompt":"昏暗室内，蓝绿色瓷砖墙面背景。一名深色短卷发人物背对镜头站立，肩背裸露，背部皮肤在冷光下呈现柔和质感，下围白色织物。左侧墙面镜子中映出人物面部，手指轻触脸颊，镜中影像清晰。整体光线微弱，冷蓝色调，人物背部占据画面右侧大部分区域，镜面反射位于左侧，构图呈现人物与镜像的对照关系。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:23:13-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_20.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.11,"observed_resolution":"normal","observation_limits":[],"id":"VP-f746533258e4f155","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-40e98ef82dc9812b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_33.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"山坡上密集排列的老旧房屋群，前景为空旷的泥土地面，天空布满灰蓝色云层，整体呈现阴冷色调。","analysis":"画面采用平视角度，前景占据约三分之一画面，为平坦的土黄色空地。中景是依山而建的密集建筑群，房屋高低错落，颜色以灰白、土黄、暗红为主。天空占据上方约三分之一，云层厚重。光线为阴天散射光，整体偏冷，明暗对比不强烈，建筑阴影柔和。","prompt":"阴冷色调的乡村山坡聚落全景，前景是大片平坦的土黄色泥土地，中景是依山势密集堆叠的老旧房屋，建筑外墙呈现灰白、土黄、暗红等斑驳色彩，屋顶多为红瓦或平顶，部分建筑可见未完工的混凝土框架结构，房屋高低错落紧密相连，背景是布满灰蓝色厚重云层的天空，整体光线为阴天散射光，氛围沉静压抑，无行人活动。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:23:20-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_33.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.128,"observed_resolution":"normal","observation_limits":[],"id":"VP-5b66a920be4cecb7","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-2613d07af80d775e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_46.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"昏暗室内，四人围坐在铺着浅色桌布的餐桌旁。桌上摆放着烛台、酒杯和食物，背景墙面挂有黑白画框，两侧墙壁亮着暖色壁灯，左侧可见通往另一房间的门口。","analysis":"画面采用平视视角，构图以餐桌为中心，人物呈半包围状分布。前景人物仅可见上半身及手臂，面部处于阴影中。背景墙面占据约三分之一画面，挂画与壁灯形成视觉平衡。整体光线昏暗，主要光源来自桌面烛火及墙壁暖色壁灯，形成强烈的明暗对比，人物面部受光不均，营造出私密且压抑的氛围。","prompt":"昏暗的室内餐厅场景，四人围坐在铺着浅色桌布的长方形餐桌旁。左侧两名男子，右侧两名女子，均仅可见上半身。桌面中央摆放着点燃的蜡烛、玻璃酒杯和盛有食物的餐盘。背景是深褐色墙面，正中挂着一幅黑白人物画框，右侧墙面有一盏亮着的方形壁灯，左侧远处门口透出暖黄光线。整体色调偏暗，以烛光与壁灯的暖橙色为主，人物面部处于阴影中，光影对比强烈，呈现出一种静谧而压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:23:28-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_46.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.118,"observed_resolution":"normal","observation_limits":[],"id":"VP-478cc9781cf67414","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-86154a54122ccd72","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_59.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"一名男子俯身探向停在草地边缘的银灰色轿车，车内有人影，车旁有一只灰狗。背景是巨大的岩石山体和覆盖植被的山坡，天空云层稀薄，阳光强烈。","analysis":"画面采用广角构图，前景人物与车辆占据左下区域，右侧及上方被巨大的山体剪影占据，环境占比极大。左侧男子仅上半身可见，身体前倾，头部低垂。车内人物面部模糊。光线来自上方偏左，形成强烈的逆光效果，天空明亮泛白，地面与山体处于阴影中，色彩呈现冷调的蓝绿色，对比强烈。","prompt":"一张写实风格的户外场景图。画面左侧前景，一名身穿深色长袖上衣的男子正弯腰探身进入一辆银灰色老式轿车的驾驶座车窗，姿态前倾。车内隐约可见另一名乘客。车辆左前轮旁站着一只毛发蓬松的灰狗。背景是连绵起伏的山丘，右侧矗立着一座巨大的、轮廓陡峭的岩石山峰，山体大部分处于背光阴影中，呈现深青灰色。天空占据画面上半部分，云层呈丝状分布，太阳位于上方，发出耀眼的白光，光线穿过云层形成逆光效果。地面是绿色的草地，整体色调偏冷，带有电影感的蓝绿色滤镜，光影对比强烈，营造出一种静谧而略带压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T11:23:36-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_59.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.119,"observed_resolution":"normal","observation_limits":[],"id":"VP-32562482a4a98fbc","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-0d9adff915526d0d","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_08.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"昏暗室内，一名穿灰毛衣的人物侧身蹲坐于长凳边缘，身旁放着红色花纹大包裹，背景是斑驳的碎花墙纸与绿色护墙板。","analysis":"画面采用暗调构图，大面积阴影占据左侧与前景，形成窥视感。人物位于画面右侧，全身可见，呈蹲坐姿态，双手交握于膝前。光线微弱，主要照亮人物侧脸与毛衣纹理，红色包裹在暗部中形成视觉重心。整体色调偏冷绿，明暗对比强烈，营造出压抑、静谧的视觉氛围。","prompt":"昏暗破旧的室内空间，一名留着黑色短发的人物身穿灰色粗针织高领毛衣，侧身蹲坐在长凳边缘，双手交握，目光望向右侧。长凳上放置着两个巨大的红色印花布包裹，图案繁复。背景墙面分为上下两部分，上方是褪色的碎花壁纸，下方是剥落的绿色护墙板，墙皮有破损痕迹。画面左侧被大面积黑色阴影遮挡，形成窥视视角。光线微弱且偏冷，仅照亮人物侧脸与衣物纹理，整体氛围压抑、静谧，具有胶片颗粒感。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:39:00+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_08.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.111,"observed_resolution":"normal","observation_limits":[],"id":"VP-730cc0df4ac2b30c","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-e537ceba0ebd6533","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_21.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"昏暗的野外，一条横向土路穿过枯草地。左侧路面上有一个模糊的人影正在行走，身后似乎跟着一只浅色动物。背景是低矮的村庄房屋和笼罩在浓雾中的连绵山丘。","analysis":"画面采用横向构图，上方天空占据约二分之一比例，几条电线横贯顶部。人物位于画面左下三分之一处，全身可见但轮廓模糊，呈行走姿态，身形较小。环境光线极暗，整体呈现冷调的蓝灰色，天空与山峦的界限被雾气模糊，前景植被与中景道路在低光下细节不清，明暗对比微弱。","prompt":"昏暗的野外风景，冷调蓝灰色光线。画面顶部有几条黑色电线横贯。背景是连绵起伏的山丘，山顶被厚重的低垂云雾笼罩，山脚下坐落着一片低矮的村庄房屋，建筑轮廓在暮色中显得灰暗。中景是一条横向延伸的土路，路面呈灰白色。路面上左侧有一个模糊的人影正在行走，身形较小，穿着深色衣物，身后紧跟着一只浅色的动物。前景是大片枯黄的杂草和灌木丛，植被细节在低光下显得模糊不清，整体氛围阴冷、压抑且静谧。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:39:08+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_21.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.11,"observed_resolution":"normal","observation_limits":[],"id":"VP-7045ee44cb2c1c5b","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-e8c37b7a8dd0de24","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_34.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"一面斑驳的灰白色混凝土墙面，表面布满裂纹与剥落的痕迹。墙面右侧嵌有一块红底矩形标牌，上面印有残缺的“DESPACIO DE GRAN”字样，标牌表面油漆严重起皮脱落，露出粗糙的底层材质。","analysis":"画面采用平视视角，构图将斑驳的墙面作为主体背景，占据了绝大部分画面空间。右侧的矩形标牌作为视觉焦点，其边缘与周围墙面的剥落纹理形成对比。光线柔和且均匀，没有强烈的明暗对比，整体色调偏向冷灰与暗红，呈现出一种陈旧、破败的质感。","prompt":"这是一张写实风格的静帧画面，展示了一面老旧的混凝土墙壁。墙面呈灰白色，表面粗糙，布满了细密的裂纹和剥落的痕迹，左侧边缘露出了红褐色的砖石结构。在画面右侧，嵌有一块矩形的红底标牌，标牌上的油漆已经严重老化，呈现出大片起皮和脱落的状态，露出了底层的深色材质。标牌上印有黑色的粗体文字，部分字母因破损而残缺不全，依稀可辨认出“DESPACIO DE GRAN”的字样。整体光线平淡，色彩饱和度较低，营造出一种荒凉、破败的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:39:17+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_34.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.126,"observed_resolution":"normal","observation_limits":[],"id":"VP-8e09f7a0598f99fe","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-a45ffbb0092e02de","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_47.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"昏暗室内，两名女性并排坐在桌边，中间立着一支燃烧的蜡烛，前景有模糊的深色物体遮挡，背景昏暗。","analysis":"画面采用过肩视角，前景右侧有模糊的深色背影占据约三分之一画面。左侧女性上半身可见，身穿米白色镂空针织衫，手托下巴；右侧女性上半身可见，身穿深褐色上衣。两人面部被烛光微弱照亮，背景几乎全黑，明暗对比强烈，色调偏暖黄。","prompt":"昏暗室内场景，两名女性并排坐在桌边。左侧女性金发，身穿米白色镂空花纹针织衫，左手托着下巴，神情凝重。右侧女性深色短发，身穿深褐色高领上衣，目光看向左侧。两人中间立着一支燃烧的长蜡烛，烛光微弱地照亮她们的面部。前景右侧有一个模糊的深色背影，占据画面右下角。背景昏暗，隐约可见椅背轮廓。整体色调偏暖黄，明暗对比强烈，营造出压抑的氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:39:23+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_47.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.109,"observed_resolution":"normal","observation_limits":[],"id":"VP-742ad0c5b2accef0","origin":"visual"},{"work_id":"src-59830252dba54de0","frame_id":"FG-b1cc0d9a6c965045","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Un_Amor_60.jpg","source_page":"https://film-grab.com/2026/04/20/un-amor/","scene":"车内后座，一名深色短发女性侧身坐着，面部朝向镜头方向，神情凝重。前景是深色座椅靠背和头枕，背景透过车窗可见模糊的户外绿色植被。","analysis":"画面采用车内视角，前景占据约三分之一画面的是深色座椅靠背和两个头枕，形成框架式构图。右侧女性上半身可见，穿着深色外套，领口处有浅色毛绒材质。光线从车窗射入，在人物面部形成柔和的侧光，整体色调偏冷，带有蓝绿色调。车窗玻璃上有轻微反光，增加了画面的层次感。","prompt":"车内后座场景，前景是深色汽车座椅靠背和两个圆形头枕，占据画面左侧和中部。右侧坐着一名深色短发女性，上半身可见，穿着深色外套，领口有浅色毛绒装饰，面部朝向镜头方向，神情凝重。光线从车窗射入，在人物面部形成柔和侧光，整体色调偏冷，带有蓝绿色调。背景透过车窗可见模糊的户外绿色植被，车窗玻璃上有轻微反光。画面具有胶片质感，颗粒感明显，氛围沉静。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-11T16:39:31+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Un_Amor_60.jpg","observed_dimensions":[1440,1078],"source_thumbnail_dimensions":[500,374],"source_image_match_mae":0.113,"observed_resolution":"normal","observation_limits":[],"id":"VP-d76aa226fc67b619","origin":"visual"}]}